List<WpisAktywnosci> sparsujLog(String[] logAktywnosci) {
    List<WpisAktywnosci> wynik = new ArrayList<>();
    for (String linia : logAktywnosci) {
        String[] czesci = linia.split(":"); // wzorzec z lekcji 2: rozbij string po separatorze
        wynik.add(new WpisAktywnosci(czesci[0], czesci[1], Integer.parseInt(czesci[2])));
    }
