}

class FriendNetwork {
    private final Map<String, List<String>> znajomi;

    FriendNetwork(Map<String, List<String>> znajomi) { this.znajomi = znajomi; }

    int stopnieOddalenia(String a, String b) { // BFS - lekcja 12
        if (a.equals(b)) return 0;
        Set<String> odwiedzone = new HashSet<>(); // LOKALNY zbior, nowy przy KAZDYM wywolaniu
        Queue<String> kolejka = new ArrayDeque<>();
        odwiedzone.add(a);
        kolejka.offer(a);
        int odleglosc = 0;
        while (!kolejka.isEmpty()) {
            int rozmiar = kolejka.size();
            odleglosc++;
            for (int i = 0; i < rozmiar; i++) {
                String osoba = kolejka.poll();
                for (String znajomy : znajomi.getOrDefault(osoba, List.of())) {
                    if (znajomy.equals(b)) return odleglosc;
                    if (odwiedzone.add(znajomy)) kolejka.offer(znajomy);
                }
            }
        }
        return -1;
    }

    int liczbaWyspSpolecznosci() { // DFS spojne skladowe - lekcja 13
        Set<String> odwiedzone = new HashSet<>(); // TEZ lokalny, niezalezny od stopnieOddalenia
        int liczba = 0;
        for (String osoba : znajomi.keySet()) {
            if (!odwiedzone.contains(osoba)) {
                liczba++;
                dfsZatop(osoba, odwiedzone);
            }
        }
        return liczba;
    }

    private void dfsZatop(String osoba, Set<String> odwiedzone) {
        odwiedzone.add(osoba);
        for (String znajomy : znajomi.getOrDefault(osoba, List.of())) {
            if (!odwiedzone.contains(znajomy)) dfsZatop(znajomy, odwiedzone);
        }
    }
}

