Optional<String> najczestszaAkcja(List<WpisAktywnosci> log) {
    Map<String, Integer> licznik = new HashMap<>();
    for (WpisAktywnosci w : log) licznik.merge(w.akcja(), 1, Integer::sum);
    return licznik.entrySet().stream()
            .max(Map.Entry.comparingByValue())
            .map(Map.Entry::getKey);
}

Optional<String> najczestszaAkcjaStream(List<WpisAktywnosci> log) {
    return log.stream()
            .collect(Collectors.groupingBy(WpisAktywnosci::akcja, Collectors.counting()))
            .entrySet().stream()
            .max(Map.Entry.comparingByValue())
            .map(Map.Entry::getKey);
}
// Obie wersje: O(n) czasu, O(k) pamięci dla k różnych akcji.

List<String> sciezka(String a, String b) {
    Map<String, String> rodzic = new HashMap<>();
    rodzic.put(a, null);
    Queue<String> kolejka = new ArrayDeque<>(List.of(a));
    while (!kolejka.isEmpty()) {
        String osoba = kolejka.poll();
        if (osoba.equals(b)) {
            LinkedList<String> wynik = new LinkedList<>();
            for (String w = b; w != null; w = rodzic.get(w)) wynik.addFirst(w);
            return wynik;
        }
        for (String z : znajomi.getOrDefault(osoba, List.of())) {
            if (!rodzic.containsKey(z)) {
                rodzic.put(z, osoba);
                kolejka.offer(z);
            }
        }
    }
    return List.of();
}
// rodzic.put(a, null) - HashMap dopuszcza wartość null, a containsKey odróżnia ją od braku klucza.

Set<String> znajomiZnajomych(String a) {
    Set<String> bezposredni = new HashSet<>(znajomi.getOrDefault(a, List.of()));
    Set<String> wynik = new HashSet<>();
    for (String z : bezposredni) {
        for (String zz : znajomi.getOrDefault(z, List.of())) {
            if (!zz.equals(a) && !bezposredni.contains(zz)) wynik.add(zz);
        }
    }
    return wynik;
}
// O(suma stopni znajomych a). Zbiór automatycznie usuwa duplikaty (ktoś może być znajomym kilku znajomych).

class FriendNetworkTest {
    FriendNetwork siec = new FriendNetwork(Map.of(
            "ala", List.of("bob", "cyt"), "bob", List.of("ala", "dan"),
            "cyt", List.of("ala"), "dan", List.of("bob"),
            "ewa", List.of("fil"), "fil", List.of("ewa"), "gra", List.of()));

    @Test void stopnieOddaleniaDlaZnajomegoZnajomego() {
        assertEquals(2, siec.stopnieOddalenia("ala", "dan"));
    }

    @Test void brakPolaczeniaZwracaMinusJeden() {
        assertEquals(-1, siec.stopnieOddalenia("ala", "ewa"));
    }

    @Test void liczyTrzyGrupy() {
        assertEquals(3, siec.liczbaWyspSpolecznosci());
    }

    @Test void kolejneWywolaniaSaNiezalezne() {
        assertEquals(2, siec.stopnieOddalenia("ala", "dan"));
        assertEquals(2, siec.stopnieOddalenia("bob", "cyt")); // wersja złamana zwraca tu -1
    }
}

